/**
 * @name Taint flow to dynamic code execution
 * @description Tracks flow from user-controlled input to dynamic code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/taint-to-code-execution
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CodeExecutionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    // CLI arguments
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source = call
    ) or
    // sys.argv
    exists(DataFlow::AttrRead attr |
      attr.getObject().asExpr().(Name).getId() = "sys" and
      attr.getAttributeName() = "argv" and
      source.asExpr() = attr.asExpr()
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().asExpr().(Name).getId() in ["compile", "getattr", "exec", "eval"] and
      sink = call.getArg(_)
    )
  }
}

module CodeExecutionFlow = TaintTracking::Global<CodeExecutionConfig>;
import CodeExecutionFlow::PathGraph

from CodeExecutionFlow::PathNode source, CodeExecutionFlow::PathNode sink
where CodeExecutionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic code execution with data from $@.", source.getNode(), "user input"
